#include <WiFi.h>
#include <WebServer.h>

const char *ssid = "ESP32_Robot";
const char *password = "12345678";

const int IN1 = 18;
const int IN2 = 19;
const int IN3 = 22;
const int IN4 = 23;

WebServer server(80);

void stopMotors() {
  digitalWrite(IN1, LOW);
  digitalWrite(IN2, LOW);
  digitalWrite(IN3, LOW);
  digitalWrite(IN4, LOW);
}

void forward() {
  digitalWrite(IN1, HIGH);
  digitalWrite(IN2, LOW);
  digitalWrite(IN3, HIGH);
  digitalWrite(IN4, LOW);
}

void backward() {
  digitalWrite(IN1, LOW);
  digitalWrite(IN2, HIGH);
  digitalWrite(IN3, LOW);
  digitalWrite(IN4, HIGH);
}

void left() {
  digitalWrite(IN1, LOW);
  digitalWrite(IN2, HIGH);
  digitalWrite(IN3, HIGH);
  digitalWrite(IN4, LOW);
}

void right() {
  digitalWrite(IN1, HIGH);
  digitalWrite(IN2, LOW);
  digitalWrite(IN3, LOW);
  digitalWrite(IN4, HIGH);
}

const char HTML_PAGE[] = R"rawliteral(
<!DOCTYPE html>
<html>
<head>
<meta name="viewport" content="width=device-width, initial-scale=1">
<style>
  body { font-family: Arial; text-align: center; background: #1e1e2f; color: white; padding-top: 30px; }
  h2 { margin-bottom: 25px; }
  .btn { display: inline-block; width: 90px; height: 90px; margin: 10px; font-size: 24px; font-weight: bold; border-radius: 50%; border: none; cursor: pointer; color: white; box-shadow: 0 4px #000; }
  .btn:active { transform: translateY(4px); box-shadow: 0 0 #000; }
  .up, .down, .left, .right { background-color: #007bff; }
  .stop { background-color: #dc3545; }
</style>
</head>
<body>
  <h2>ESP32 Robot Controller</h2>
  <div><button class="btn up" onclick="cmd('/f')">&#9650;</button></div>
  <div>
    <button class="btn left" onclick="cmd('/l')">&#9664;</button>
    <button class="btn stop" onclick="cmd('/s')">&#9632;</button>
    <button class="btn right" onclick="cmd('/r')">&#9654;</button>
  </div>
  <div><button class="btn down" onclick="cmd('/b')">&#9660;</button></div>

  <script>
    function cmd(action) { fetch(action); }
  </script>
</body>
</html>
)rawliteral";

void handleRoot() {
  server.send(200, "text/html", HTML_PAGE);
}

void setup() {
  Serial.begin(115200);

  pinMode(IN1, OUTPUT);
  pinMode(IN2, OUTPUT);
  pinMode(IN3, OUTPUT);
  pinMode(IN4, OUTPUT);
  stopMotors();

  WiFi.softAP(ssid, password);
  Serial.println("\nAP Started!");
  Serial.print("IP Address: ");
  Serial.println(WiFi.softAPIP());

  server.on("/", handleRoot);
  server.on("/f", []() { forward(); server.send(200, "text/plain", "OK"); });
  server.on("/b", []() { backward(); server.send(200, "text/plain", "OK"); });
  server.on("/l", []() { left(); server.send(200, "text/plain", "OK"); });
  server.on("/r", []() { right(); server.send(200, "text/plain", "OK"); });
  server.on("/s", []() { stopMotors(); server.send(200, "text/plain", "OK"); });

  server.begin();
  Serial.println("HTTP Server Started");
}

void loop() {
  server.handleClient();
}
